from pathlib import Path
import json,statistics
W=Path(__file__).parent
load=lambda p:json.loads((W/p).read_text())
lines=['# Measured block/render hotspot results','','Generated by `make-results.py` from archived observations. Negative changes mean less elapsed time. Paired timings and the native Ox comparison use separate drivers.','', '## Repeated production measurements','','Three fresh process pairs; nine alternating 75 ms windows per implementation/input after 60 ms warmup. Each row reports the median absolute time across the three process medians and each pair’s relative change.','','| Input | Baseline µs | Production µs | Pair 1 | Pair 2 | Pair 3 |','| --- | ---: | ---: | ---: | ---: | ---: |']
runs=[load(f'production/confirm-{i}/summary.json') for i in range(1,4)]
for rows in zip(*runs):
 a,b=[statistics.median(r[k] for r in rows)/1000 for k in ['baseline_ns','candidate_ns']]
 lines.append('| '+rows[0]['case']+f' | {a:.3f} | {b:.3f} | '+' | '.join(f"{r['change_pct']:+.2f}%" for r in rows)+' |')
repeated=[r[0]['case'] for r in zip(*runs) if all(x['change_pct']>2 for x in r)]
lines+=['',f'Inputs slower by more than 2% in all three pairs: {len(repeated)}. '+', '.join(repeated),'','## Exploratory screens','','Five alternating 30 ms windows after 60 ms warmup. The first four screens have 81 inputs; later screens have 93. These are single screens, not confirmation runs.','','| Candidate | Inputs | Cross-input median | Vue render function | MSBuild | Compiler Options | Short root HTML |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for p in sorted(W.glob('*/summary.json')):
 if not p.with_name('windows.jsonl.gz').exists():continue
 rows=json.loads(p.read_text());by={r['index']:r for r in rows}
 lines.append(f'| {p.parent.name} | {len(rows)} | {statistics.median(r["change_pct"] for r in rows):+.2f}% | '+' | '.join(f'{by[i]["change_pct"]:+.2f}%' for i in [108,612,613,694])+' |')
lines+=['','## Large-input latency confirmation','','The eight inputs of at least 8,000,000 bytes from the memory dataset are also timed with the native production driver and explicit fresh-render flags. Three process pairs use five alternating windows with a requested minimum of 30 ms and 60 ms warmup. The driver checks elapsed time after each 16-render batch, so these large-input windows can be substantially longer; raw counts and elapsed times determine every median.','','| Input | Baseline ms | Production ms | Pair 1 | Pair 2 | Pair 3 |','| --- | ---: | ---: | ---: | ---: | ---: |']
large_runs=[load(f'large/confirm-{i}/summary.json') for i in range(1,4)]
for rows in zip(*large_runs):
 a,b=[statistics.median(r[k] for r in rows)/1e6 for k in ['baseline_ns','candidate_ns']]
 lines.append('| '+rows[0]['case']+f' | {a:.3f} | {b:.3f} | '+' | '.join(f"{r['change_pct']:+.2f}%" for r in rows)+' |')
lines+=['','## Requested allocations','','57 inputs, three fresh processes per source, ten observations each. Input storage is excluded; owned HTML remains live. These counters are not RSS. All observations per source/input agree.','','| Input | Bytes | Peak before | Peak after | Change | Calls before | Calls after |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for a,b in zip(load('memory/baseline/summary.json'),load('memory/production/summary.json')):
 assert a['case']==b['case'] and a['html_sha256']==b['html_sha256']
 change=(b['peak_live_bytes']/a['peak_live_bytes']-1)*100 if a['peak_live_bytes'] else 0
 lines.append(f'| {a["case"]} | {a["input_bytes"]} | {a["peak_live_bytes"]} | {b["peak_live_bytes"]} | {change:+.2f}% | {a["allocation_calls"]} | {b["allocation_calls"]} |')
lines+=['','## Fresh native Ox corpus comparison','','Heading IDs enabled. Ox growing arena is primary; presizing is separate. Three process groups, nine rotating 60 ms windows after 35 ms warmup. Medians below combine the three process medians. Ratios above 1 mean Ferromark takes longer. Only equal normalized outputs support the comparison.','','| Input | Equal | Ferromark µs | Ox grow µs | Ox presize µs | F/grow |','| --- | --- | ---: | ---: | ---: | ---: |']
corpus=[load(f'corpus/final-{i}-summary.json') for i in range(1,4)]
for rows in zip(*corpus):
 times={e:statistics.median(r['median_ns'][e] for r in rows)/1000 for e in ['ferro','ox-grow','ox-presize']}
 ratio=f'{times["ferro"]/times["ox-grow"]:.3f}' if rows[0]['equal'] else 'n/a'
 lines.append(f'| {rows[0]["case"]} | {rows[0]["equal"]} | {times["ferro"]:.3f} | {times["ox-grow"]:.3f} | {times["ox-presize"]:.3f} | {ratio} |')
verification=load('corpus/verification.json');lines+=['',f'Corpus output verification: {sum(r["equal"] for r in verification)}/{len(verification)} normalized outputs equal. Mismatches remain explicit diagnostics.','','## Exact-output guards','','| Guard | Comparisons | Failures |','| --- | ---: | ---: |']
total=0
for file in ['verification.json','extra-verification.json','extended-verification.json','block-verification.json','fence-verification.json','timing-verification.json']:
 r=load('production/'+file);failed=r.get('failed',r.get('failures'));assert not failed;total+=r['count'];lines.append(f'| {file} | {r["count"]} | {len(failed)} |')
lines+=['',f'Total: {total:,} logical comparisons. The replay rebuilds both sources and checks the baseline against the archived oracles first.']
(W/'RESULTS.md').write_text('\n'.join(line.rstrip() for line in lines).rstrip()+'\n')

summary=['## Confirmed outcomes','','| Document | Baseline µs | Production µs | Relative changes across three pairs |','| --- | ---: | ---: | --- |']
for index,label in [(613,'Compiler Options'),(612,'Compiler Options in MSBuild'),(108,'Vue render function'),(79,'Vue Suspense')]:
 rows=[next(r for r in run if r['index']==index) for run in runs]
 a,b=[statistics.median(r[k] for r in rows)/1000 for k in ['baseline_ns','candidate_ns']]
 summary.append(f'| {label} | {a:.3f} | {b:.3f} | '+', '.join(f"{r['change_pct']:+.2f}%" for r in rows)+' |')
summary+=['',f'{len(repeated)} of 93 inputs are more than 2% slower in all three pairs. Individual changes and all raw observations remain visible in RESULTS.md.','','Representative large-input requested heap peaks (owned HTML live, input excluded):','','| Input | Bytes | Baseline peak bytes | Production peak bytes | Change |','| --- | ---: | ---: | ---: | ---: |']
for a,b in zip(load('memory/baseline/summary.json'),load('memory/production/summary.json')):
 if a['input_bytes']>=8000000:
  pct=(b['peak_live_bytes']/a['peak_live_bytes']-1)*100
  summary.append(f'| {a["case"]} | {a["input_bytes"]} | {a["peak_live_bytes"]} | {b["peak_live_bytes"]} | {pct:+.2f}% |')
report=(W/'REPORT.md').read_text();start=report.index('<!-- measured-summary:start -->')+len('<!-- measured-summary:start -->');end=report.index('<!-- measured-summary:end -->');report=report[:start]+'\n\n'+'\n'.join(summary)+'\n\n'+report[end:];(W/'REPORT.md').write_text(report)
